// @generated by:gauntlet run:godseye-local-agent-center
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { owner, projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("authenticated strict Agent Center HTTP", () => {
  let fixture: OwnerAuthFixture;
  let headers: Headers;
  let infrastructure: InfrastructureEngine;
  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    infrastructure = new InfrastructureEngine(fixture.store);
  });
  afterEach(async () => {
    await fixture.close();
  });
  const app = () =>
    createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      infrastructure.foundation,
      undefined,
      infrastructure,
    );
  async function profile() {
    const project = await fixture.core.createProject(owner, projectInput, randomUUID());
    const environment = project.environments.find((env) => env.kind === "development");
    if (!environment) throw new Error("Missing Agent HTTP fixture environment");
    const input = {
      projectId: project.id,
      environmentId: environment.id,
      role: "operations",
      model: "gpt-6-luna",
      expectedProjectRevision: project.revision,
      expectedEnvironmentRevision: environment.revision,
      limits: {
        maxOutputTokens: 1024,
        timeoutSeconds: 120,
        maxCostMicros: 10000,
        maxTurns: 1,
        maxRequests: 1,
      },
    };
    return { project, environment, input };
  }
  const request = (path: string, body: unknown, key = randomUUID()) =>
    app().request(new URL(`/api/v1${path}`, fixture.origin), {
      method: "POST",
      headers: new Headers([...headers, ["idempotency-key", key]]),
      body: JSON.stringify(body),
    });

  it("T-AC-721 authenticates every Agent Center route before interpreting caller bodies", async () => {
    for (const [method, path] of [
      ["GET", "/agents"],
      ["POST", "/agents/profiles"],
      ["POST", `/agents/profiles/${randomUUID()}/configure`],
      ["POST", `/agents/profiles/${randomUUID()}/pause`],
      ["POST", `/agents/profiles/${randomUUID()}/resume`],
      ["POST", "/agents/tasks"],
      ["GET", `/agents/tasks/${randomUUID()}`],
      ["POST", `/agents/tasks/${randomUUID()}/cancel`],
      ["POST", `/agents/tasks/${randomUUID()}/reconcile`],
    ] as const) {
      const response = await app().request(new URL(`/api/v1${path}`, fixture.origin), {
        method,
        headers: fixture.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });
  it("T-AC-731 publishes unavailable metadata without private runtime material", async () => {
    const response = await app().request(new URL("/api/v1/agents", fixture.origin), { headers });
    expect(response.status).toBe(200);
    expect(response.headers.get(CONTROL_API_HEADER)).toBe(CONTROL_API_VERSION);
    expect(await response.json()).toMatchObject({
      status: "unconfigured",
      profiles: [],
      tasks: [],
      tools: [],
    });
  });
  it("T-AC-721 accepts scoped profile creation through the owner boundary and retains idempotency", async () => {
    const { input } = await profile(),
      key = randomUUID();
    const first = await request("/agents/profiles", input, key);
    expect(first.status).toBe(201);
    const created = await first.json();
    const again = await request("/agents/profiles", input, key);
    expect(again.status).toBe(201);
    expect(await again.json()).toEqual(created);
    expect(created).toMatchObject({
      projectId: input.projectId,
      environmentId: input.environmentId,
      model: "gpt-6-luna",
      runtime: "unconfigured",
      tools: [],
    });
  });
  it("T-AC-731 refuses unknown authority fields and absent idempotency without state mutation", async () => {
    const { input } = await profile();
    const noKey = await app().request(new URL("/api/v1/agents/profiles", fixture.origin), {
      method: "POST",
      headers,
      body: JSON.stringify(input),
    });
    expect(noKey.status).toBe(400);
    const injection = await request("/agents/profiles", {
      ...input,
      endpoint: "http://127.0.0.1/management",
    });
    expect(injection.status).toBe(422);
    expect((await infrastructure.agents.overview(owner)).profiles).toHaveLength(0);
  });
  it("T-AC-723 refuses unconfigured launch with no persisted fake-success task", async () => {
    const { input } = await profile();
    const created = await (await request("/agents/profiles", input)).json();
    const response = await request("/agents/tasks", {
      profileId: created.id,
      expectedRevision: created.revision,
      input: "Short task",
    });
    expect(response.status).toBe(503);
    expect(await response.json()).toMatchObject({ error: { code: "CAPABILITY_UNAVAILABLE" } });
    expect((await infrastructure.agents.overview(owner)).tasks).toHaveLength(0);
  });
});
